/* Theodore public-page cache. Authenticated and private requests always go directly to the network. */
const CACHE_NAME='theodore-public-safe-v2';
const privatePath=path=>path==='/admin'||path.startsWith('/admin/')||path==='/private'||path.startsWith('/private/');
self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',event=>event.waitUntil((async()=>{const keys=await caches.keys();await Promise.all(keys.filter(key=>key!==CACHE_NAME).map(key=>caches.delete(key)));await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data==='SKIP_WAITING')self.skipWaiting();});
self.addEventListener('fetch',event=>{
 const request=event.request,url=new URL(request.url);
 // Check BEFORE looking in CacheStorage: old responses must not be returned for a different credential.
 if(request.method!=='GET'||url.origin!==self.location.origin||request.headers.has('authorization')||request.headers.has('range')||privatePath(url.pathname)){
  event.respondWith(fetch(request,{cache:'no-store'}));return;
 }
 event.respondWith((async()=>{try{const response=await fetch(request);if(response.ok&&response.type==='basic'){const cache=await caches.open(CACHE_NAME);await cache.put(request,response.clone());}return response;}catch(error){const saved=await caches.match(request);if(saved)return saved;throw error;}})());
});
